	"taskai/ent"
	"taskai/ent/team"
	"taskai/ent/teammember"
	"taskai/ent/teaminvitation"
	"taskai/ent/user"
)

type Team struct {
	ID        int64     `json:"id"`
	Name      string    `json:"name"`
	OwnerID   int64     `json:"owner_id"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

type TeamMember struct {
	ID       int64     `json:"id"`
