	ts.HandleGetCollaborators(rec, req)
	var ownerView []Collaborator
	DecodeJSON(t, rec, &ownerView)
	if len(ownerView) != 3 || ownerView[0].TeamName != "Elastio" {
		t.Errorf("unexpected owner view %+v", ownerView)
	}
}

